using System.Text;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;using StudentCenter.ApplicationService.Application.Interfaces;using StudentCenter.ApplicationService.Application.Services;using StudentCenter.ApplicationService.Infrastructure.ExternalServices;using StudentCenter.ApplicationService.Infrastructure.Persistence;using StudentCenter.ApplicationService.Infrastructure.Repositories;
var b=WebApplication.CreateBuilder(args);var j=b.Configuration.GetSection("Jwt");b.Services.AddControllers();b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen(o=>{o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});b.Services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlServer(b.Configuration.GetConnectionString("ApplicationDb")));b.Services.AddHttpContextAccessor();b.Services.AddHttpClient<IStudentClient,StudentClient>(c=>c.BaseAddress=new Uri("https://localhost:49686/"));b.Services.AddScoped<ICompetitionRepository,CompetitionRepository>();b.Services.AddScoped<IApplicationRepository,ApplicationRepository>();b.Services.AddScoped<CompetitionService>();b.Services.AddScoped<ApplicationService>();b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=j["Issuer"],ValidateAudience=true,ValidAudience=j["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(j["Key"]!)),ValidateLifetime=true});b.Services.AddAuthorization();var a=b.Build();using(var s=a.Services.CreateScope())await s.ServiceProvider.GetRequiredService<ApplicationDbContext>().Database.MigrateAsync();if(a.Environment.IsDevelopment()){a.UseSwagger();a.UseSwaggerUI();}a.UseAuthentication();a.UseAuthorization();a.MapControllers();a.Run();
